def _tags(checkouts):
    """(supported_in constants, human text) for a set of checkouts.

    The generator precomputes every set the tables below can produce, so the
    per-release fallback should never run; it is here so that an unforeseen
    combination degrades to a longer label rather than a KeyError.
    """
    key = tuple(checkouts)
    hit = _TAGS.get(key)
    if hit is not None:
        return hit
    return (tuple(_RELEASE[v][0] for v in key),
            ", ".join(_RELEASE[v][1] for v in key))


def _union(sets):
    return tuple(v for v in _ORDER if any(v in s for s in sets))


def _coeff_entry(model, category, name, src, groups, present, absent,
                 doc="", upstream_note=""):
    consts, _ = _tags(present)
    # A group with no raw value is a required read: the source has no fallback,
    # so there is no default to state. `required` is claimed only when that
    # holds in every release this module covers.
    defaulted = [(raw, where) for raw, where in groups if raw is not None]
    required = not defaulted
    # The default field takes a single value, so it is filled only when there
    # is exactly one. Two groups means the default changed between releases and
    # a scalar cannot say which is which -- the ChoiceItems below carry them
    # with their own version tags, which is the only honest spelling.
    default = defaulted[0][0] if len(groups) == 1 and defaulted else ""
    # Upstream's own words first, then the mechanical sentence. The default
    # itself is no longer narrated here: it lives in `default` (or in the
    # choices), so the fact has exactly one spelling.
    presence = f"Only present in {_tags(present)[1]}." if absent else ""
    schema = KeySchema(
        key=name,
        label=name,
        description=(
            (doc.rstrip(" .:") + ". " if doc else "")
            + f"{model} ({category}) model coefficient, "
            f"read in the {src} constructor."),
        supported_in=consts,
        default=default,
        required=required,
        note=" ".join(x for x in (upstream_note, presence) if x),
        choices=tuple(
            ChoiceItem(
                value=raw,
                description=f"Source default in {_tags(where)[1]}.",
                supported_in=_tags(where)[0],
            )
            for raw, where in defaulted),
    )
    return schema


def _merged_plain(name, owners):
    """One flat entry for a coefficient several models read.

    OpenFOAM reads these through optionalSubDict, so `RAS { Cmu 0.09; }` is
    legal and common. Naming a single owner would attribute one model's
    default to another's dictionary, and dropping the entry would leave the
    flat spelling unexplained — so the entry names every owner and offers
    every distinct default.
    """
    models = sorted({o["model"] for o in owners})
    if len(models) == 1:
        return owners[0]["schema"]

    by_value = {}
    for o in owners:
        for raw, where in o["groups"]:
            if raw is None:
                continue
            e = by_value.setdefault(raw, {"models": [], "where": []})
            if o["model"] not in e["models"]:
                e["models"].append(o["model"])
            e["where"].append(where)

    choices = []
    for raw, e in by_value.items():
        where = _union(e["where"])
        choices.append(ChoiceItem(
            value=raw,
            description=(f"Default for {', '.join(sorted(e['models']))} "
                         f"in {_tags(where)[1]}."),
            supported_in=_tags(where)[0],
        ))

    # `default` stays empty here however few values there are. A scalar cannot
    # say "0.09 under kEpsilon, 0.0845 under RNGkEpsilon", and this entry exists
    # precisely because the key has more than one owner. The ChoiceItems above
    # carry each owner's value; `required` is claimed only if no owner has a
    # default at all, so one required owner cannot make the shared key
    # mandatory for the rest.
    return KeySchema(
        key=name,
        label=name,
        description=(
            f"Coefficient of {len(models)} models: {', '.join(models)}. Read "
            f"via optionalSubDict, so it may be written directly in the parent "
            f"RAS or LES dictionary — inside a <model>Coeffs dictionary that "
            f"model's own entry applies."),
        supported_in=_tags(_union([o["present"] for o in owners]))[0],
        required=not by_value,
        note=(f"The {len(models)} models that read it do not agree on a "
              f"default; each is listed below." if len(by_value) > 1 else ""),
        choices=tuple(choices),
    )


def build_schemas(target_file: str) -> dict[str, KeySchema]:
    """The KeySchema table for one dictionary file."""
    within = set(_TARGET_CHECKOUTS.get(target_file, ()))
    table: dict[str, KeySchema] = {}
    plain: dict[str, list] = {}

    for model, category, all_checkouts, model_desc, model_note in _MODELS:
        checkouts = tuple(v for v in all_checkouts if v in within)
        if not checkouts:
            continue
        mine = [c for c in _COEFFS
                if c[0] == model and any(v in within for v in c[4])]
        if not mine:
            continue
        coeffs_dict = model + "Coeffs"
        prose = _COEFF_PROSE.get(model, {})
        container = KeySchema(
            key=coeffs_dict,
            label=model + " Coefficients",
            note=model_note,
            description=((model_desc.rstrip(" .:") + ". ")
                         if model_desc else "") + (
                f"Optional coefficient sub-dictionary for the {model} "
                f"{category} model. Read via optionalSubDict, so the "
                f"coefficients below may also be placed directly in the "
                f"parent {category} dictionary. {len(mine)} coefficients "
                f"covered by the foamlore store."),
            supported_in=_tags(checkouts)[0],
        )
        # Both spellings. FoDE resolves "<parent>.<key>" before a plain key,
        # and turbulence_structure carries a generic "<RAS|LES>.<model>Coeffs"
        # placeholder for models the generated modules do not cover — which
        # would otherwise outrank this entry and hide the model's own
        # description.
        table[coeffs_dict] = container
        table[category + "." + coeffs_dict] = container
        for _, name, src, groups, present_in in mine:
            present = tuple(v for v in present_in if v in within)
            absent = tuple(v for v in checkouts if v not in present_in)
            here = tuple((raw, tuple(v for v in where if v in within))
                         for raw, where in groups
                         if any(v in within for v in where))
            schema = _coeff_entry(
                model, category, name, src, here, present, absent,
                *prose.get(name, ("", "")))
            table[coeffs_dict + "." + name] = schema
            plain.setdefault(name, []).append(
                {"model": model, "schema": schema,
                 "present": present, "groups": here})

    for name, owners in plain.items():
        table[name] = _merged_plain(name, owners)
    return table


# model -> (upstream description, upstream note), for a consumer that names a
# model where its coefficient dictionary need not exist — FoDE's RAS/LES model
# selectors, whose choice list is a structural fact the hand-written module
# owns while the prose for each name is extracted here. Target-independent:
# what a model *is* does not depend on which file selects it.
MODEL_DOCS: dict[str, tuple[str, str]] = {
    model: (desc, note) for model, _cat, _checkouts, desc, note in _MODELS
}
